USE icaro_ops;

START TRANSACTION;

/*
 * Aircraft catalog import complete-schema migration.
 *
 * Do not rerun 108, 109, 110, 111 or 112.
 *
 * This migration is generated against the real aircraft_models schema provided
 * by DESCRIBE aircraft_models.
 *
 * Design:
 * - no aircraft progression lock
 * - all aircraft visible from registration
 * - budget is the only purchase blocker
 * - existing rows are not deleted
 * - missing rows are inserted
 * - existing rows are lightly corrected only where safe
 */

DROP TEMPORARY TABLE IF EXISTS tmp_aircraft_catalog_import;

CREATE TEMPORARY TABLE tmp_aircraft_catalog_import (
  model_code VARCHAR(40) NOT NULL,
  manufacturer VARCHAR(80) NOT NULL,
  model_name VARCHAR(120) NOT NULL,
  icao_type_code VARCHAR(8) NOT NULL,
  iata_type_code VARCHAR(8) NOT NULL,
  aircraft_family VARCHAR(80) NOT NULL,
  aircraft_category VARCHAR(40) NOT NULL,
  operation_role VARCHAR(40) NOT NULL,
  engine_type VARCHAR(40) NOT NULL,
  engine_count INT UNSIGNED NOT NULL,
  crew_required_min INT UNSIGNED NOT NULL,
  passenger_capacity_standard INT UNSIGNED NOT NULL,
  passenger_capacity_max INT UNSIGNED NOT NULL,
  cargo_capacity_kg INT UNSIGNED NOT NULL,
  max_payload_kg INT UNSIGNED NOT NULL,
  max_takeoff_weight_kg INT UNSIGNED NOT NULL,
  cruise_speed_kmh INT UNSIGNED NOT NULL,
  range_km INT UNSIGNED NOT NULL,
  service_ceiling_ft INT UNSIGNED NOT NULL,
  required_runway_m INT UNSIGNED NOT NULL,
  fuel_burn_kg_per_hour INT UNSIGNED NOT NULL,
  maintenance_cost_per_hour DECIMAL(14,2) NOT NULL,
  new_purchase_price DECIMAL(15,2) NOT NULL,
  estimated_used_price_min DECIMAL(15,2) NOT NULL,
  estimated_used_price_max DECIMAL(15,2) NOT NULL,
  lease_price_per_day DECIMAL(14,2) NOT NULL,
  currency_code CHAR(3) NOT NULL,
  production_status VARCHAR(30) NOT NULL,
  is_available_new INT UNSIGNED NOT NULL,
  is_available_used INT UNSIGNED NOT NULL,
  is_active INT UNSIGNED NOT NULL,
  is_endgame INT UNSIGNED NOT NULL,
  unlock_reputation_score INT UNSIGNED NOT NULL,
  minimum_airport_size_tier VARCHAR(40) NOT NULL,
  gameplay_notes VARCHAR(500) NOT NULL,
  data_source_name VARCHAR(255) NOT NULL,
  data_source_url VARCHAR(500) NOT NULL,
  data_quality VARCHAR(40) NOT NULL,
  iata_code VARCHAR(20) NULL,
  base_purchase_price DECIMAL(14,2) NOT NULL,
  PRIMARY KEY (model_code),
  INDEX idx_tmp_aircraft_catalog_price (new_purchase_price),
  INDEX idx_tmp_aircraft_catalog_icao (icao_type_code)
);

