INSERT INTO aircraft_models (
  model_code,
  manufacturer,
  model_name,
  icao_type_code,
  iata_type_code,
  aircraft_family,
  aircraft_category,
  operation_role,
  engine_type,
  engine_count,
  crew_required_min,
  passenger_capacity_standard,
  passenger_capacity_max,
  cargo_capacity_kg,
  max_payload_kg,
  max_takeoff_weight_kg,
  cruise_speed_kmh,
  range_km,
  service_ceiling_ft,
  required_runway_m,
  fuel_burn_kg_per_hour,
  maintenance_cost_per_hour,
  new_purchase_price,
  estimated_used_price_min,
  estimated_used_price_max,
  lease_price_per_day,
  currency_code,
  production_status,
  is_available_new,
  is_available_used,
  is_active,
  is_endgame,
  unlock_reputation_score,
  minimum_airport_size_tier,
  gameplay_notes,
  data_source_name,
  data_source_url,
  data_quality,
  iata_code,
  base_purchase_price
)
SELECT
  src.model_code,
  src.manufacturer,
  src.model_name,
  src.icao_type_code,
  src.iata_type_code,
  src.aircraft_family,
  src.aircraft_category,
  src.operation_role,
  src.engine_type,
  src.engine_count,
  src.crew_required_min,
  src.passenger_capacity_standard,
  src.passenger_capacity_max,
  src.cargo_capacity_kg,
  src.max_payload_kg,
  src.max_takeoff_weight_kg,
  src.cruise_speed_kmh,
  src.range_km,
  src.service_ceiling_ft,
  src.required_runway_m,
  src.fuel_burn_kg_per_hour,
  src.maintenance_cost_per_hour,
  src.new_purchase_price,
  src.estimated_used_price_min,
  src.estimated_used_price_max,
  src.lease_price_per_day,
  src.currency_code,
  src.production_status,
  src.is_available_new,
  src.is_available_used,
  src.is_active,
  src.is_endgame,
  src.unlock_reputation_score,
  src.minimum_airport_size_tier,
  src.gameplay_notes,
  src.data_source_name,
  src.data_source_url,
  src.data_quality,
  src.iata_code,
  src.base_purchase_price
FROM tmp_aircraft_catalog_import src
WHERE NOT EXISTS (
  SELECT 1
  FROM aircraft_models am
  WHERE am.model_code = src.model_code
);

UPDATE aircraft_models am
JOIN tmp_aircraft_catalog_import src
  ON src.model_code = am.model_code
SET
  am.manufacturer = COALESCE(NULLIF(am.manufacturer, ''), src.manufacturer),
  am.model_name = COALESCE(NULLIF(am.model_name, ''), src.model_name),
  am.icao_type_code = COALESCE(NULLIF(am.icao_type_code, ''), src.icao_type_code),
  am.iata_type_code = COALESCE(NULLIF(am.iata_type_code, ''), src.iata_type_code),
  am.aircraft_family = COALESCE(NULLIF(am.aircraft_family, ''), src.aircraft_family),
  am.aircraft_category = COALESCE(NULLIF(am.aircraft_category, ''), src.aircraft_category),
  am.operation_role = COALESCE(NULLIF(am.operation_role, ''), src.operation_role),
  am.engine_type = COALESCE(NULLIF(am.engine_type, ''), src.engine_type),
  am.engine_count = CASE WHEN am.engine_count IS NULL THEN src.engine_count ELSE am.engine_count END,
  am.crew_required_min = CASE WHEN am.crew_required_min IS NULL THEN src.crew_required_min ELSE am.crew_required_min END,
  am.passenger_capacity_standard = CASE WHEN am.passenger_capacity_standard IS NULL OR am.passenger_capacity_standard <= 0 THEN src.passenger_capacity_standard ELSE am.passenger_capacity_standard END,
  am.passenger_capacity_max = CASE WHEN am.passenger_capacity_max IS NULL OR am.passenger_capacity_max <= 0 THEN src.passenger_capacity_max ELSE am.passenger_capacity_max END,
  am.cargo_capacity_kg = CASE WHEN am.cargo_capacity_kg IS NULL THEN src.cargo_capacity_kg ELSE am.cargo_capacity_kg END,
  am.max_payload_kg = CASE WHEN am.max_payload_kg IS NULL THEN src.max_payload_kg ELSE am.max_payload_kg END,
  am.max_takeoff_weight_kg = CASE WHEN am.max_takeoff_weight_kg IS NULL THEN src.max_takeoff_weight_kg ELSE am.max_takeoff_weight_kg END,
  am.cruise_speed_kmh = CASE WHEN am.cruise_speed_kmh IS NULL OR am.cruise_speed_kmh <= 0 THEN src.cruise_speed_kmh ELSE am.cruise_speed_kmh END,
  am.range_km = CASE WHEN am.range_km IS NULL OR am.range_km <= 0 THEN src.range_km ELSE am.range_km END,
  am.service_ceiling_ft = CASE WHEN am.service_ceiling_ft IS NULL THEN src.service_ceiling_ft ELSE am.service_ceiling_ft END,
  am.required_runway_m = CASE WHEN am.required_runway_m IS NULL THEN src.required_runway_m ELSE am.required_runway_m END,
  am.fuel_burn_kg_per_hour = CASE WHEN am.fuel_burn_kg_per_hour IS NULL OR am.fuel_burn_kg_per_hour <= 0 THEN src.fuel_burn_kg_per_hour ELSE am.fuel_burn_kg_per_hour END,
  am.maintenance_cost_per_hour = CASE WHEN am.maintenance_cost_per_hour IS NULL OR am.maintenance_cost_per_hour <= 0 THEN src.maintenance_cost_per_hour ELSE am.maintenance_cost_per_hour END,
  am.new_purchase_price = CASE WHEN am.new_purchase_price IS NULL OR am.new_purchase_price <= 0 THEN src.new_purchase_price ELSE am.new_purchase_price END,
  am.estimated_used_price_min = CASE WHEN am.estimated_used_price_min IS NULL OR am.estimated_used_price_min <= 0 THEN src.estimated_used_price_min ELSE am.estimated_used_price_min END,
  am.estimated_used_price_max = CASE WHEN am.estimated_used_price_max IS NULL OR am.estimated_used_price_max <= 0 THEN src.estimated_used_price_max ELSE am.estimated_used_price_max END,
  am.lease_price_per_day = CASE WHEN am.lease_price_per_day IS NULL OR am.lease_price_per_day <= 0 THEN src.lease_price_per_day ELSE am.lease_price_per_day END,
  am.currency_code = COALESCE(NULLIF(am.currency_code, ''), src.currency_code),
  am.production_status = COALESCE(NULLIF(am.production_status, ''), src.production_status),
  am.is_available_new = CASE WHEN am.is_available_new IS NULL THEN src.is_available_new ELSE am.is_available_new END,
  am.is_available_used = CASE WHEN am.is_available_used IS NULL THEN src.is_available_used ELSE am.is_available_used END,
  am.is_active = CASE WHEN am.is_active IS NULL THEN src.is_active ELSE am.is_active END,
  am.is_endgame = CASE WHEN am.is_endgame IS NULL THEN src.is_endgame ELSE am.is_endgame END,
  am.unlock_reputation_score = CASE WHEN am.unlock_reputation_score IS NULL THEN src.unlock_reputation_score ELSE am.unlock_reputation_score END,
  am.minimum_airport_size_tier = COALESCE(NULLIF(am.minimum_airport_size_tier, ''), src.minimum_airport_size_tier),
  am.gameplay_notes = COALESCE(NULLIF(am.gameplay_notes, ''), src.gameplay_notes),
  am.data_source_name = COALESCE(NULLIF(am.data_source_name, ''), src.data_source_name),
  am.data_source_url = COALESCE(NULLIF(am.data_source_url, ''), src.data_source_url),
  am.data_quality = COALESCE(NULLIF(am.data_quality, ''), src.data_quality),
  am.iata_code = COALESCE(NULLIF(am.iata_code, ''), src.iata_code),
  am.base_purchase_price = CASE WHEN am.base_purchase_price IS NULL OR am.base_purchase_price <= 0 THEN src.base_purchase_price ELSE am.base_purchase_price END;

COMMIT;

SELECT COUNT(*) AS imported_source_rows
FROM tmp_aircraft_catalog_import;

SELECT
  model_code,
  aircraft_family,
  operation_role,
  engine_type,
  engine_count,
  crew_required_min,
  iata_type_code,
  icao_type_code,
  manufacturer,
  model_name,
  passenger_capacity_standard,
  new_purchase_price
FROM aircraft_models
ORDER BY new_purchase_price ASC, model_code ASC
LIMIT 30;
